(()=>{const root=document.getElementById('saleson-editorial');root.querySelectorAll('[data-se-view]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-se-view]').forEach(peer=>peer.setAttribute('aria-pressed',String(peer===button)));root.querySelectorAll('[data-screen]').forEach(screen=>{const active=screen.dataset.screen===button.dataset.seView;screen.hidden=!active;screen.classList.toggle('se-screen-enter',active);});root.querySelector('#se-screen-status').textContent=button.dataset.seView==='overview'?'A shared view of the working day':'Recent orders and recorded activity, side by side';}));})();
(()=>{const root=document.getElementById('saleson-editorial'),tabs=[...root.querySelectorAll('.se-team-tabs [role="tab"]')];function select(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;root.querySelector('#'+t.getAttribute('aria-controls')).hidden=!active})}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();select(tabs[n]);tabs[n].focus()})})})();
(()=>{const tabs=[...document.querySelectorAll('.cp-tabs [role="tab"]')];function select(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!active;});}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight'||e.key==='ArrowLeft')n=(i+1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();select(tabs[n]);tabs[n].focus();});});})();
